public ValueTask<int> GetCachedValueAsync(string key, CancellationToken ct)
{
    if (_cache.TryGetValue(key, out int value))
    {
        // Returned directly — no Task<T> allocation
        return new ValueTask<int>(value);
    }

    // Must return a Task<T> because result is not ready yet
    return new ValueTask<int>(LoadFromDatabaseAsync(key, ct));
}
